const fs = require("node:fs");
const path = require("node:path");

const { withDangerousMod, withXcodeProject } = require("@expo/config-plugins");

/**
 * The Live Activity widget extension.
 *
 * `ios/` is generated by `expo prebuild` and gitignored, so a widget target
 * added in Xcode by hand survives exactly until the next build. This writes one
 * into the generated project instead, from sources kept in `widget/` and
 * `modules/run-sheet-activity/`.
 *
 * A widget extension is a second binary inside the app: its own target, its own
 * bundle identifier, its own Info.plist, embedded into the app's PlugIns
 * folder. None of that is something `expo prebuild` knows how to produce — this
 * is the piece that has no Expo equivalent, which is why it is here rather than
 * in `app.config.ts`.
 *
 * Signing is left automatic. `scripts/build-ipa.sh` archives with
 * `-allowProvisioningUpdates`, so Xcode issues a profile for the extension's
 * identifier the first time it is asked and the store build needs no new key.
 */

const TARGET = "RunSheetWidget";

/** Sources compiled into the widget, copied in from where they are edited. */
const SOURCES = [
  ["widget", "RunSheetWidgetBundle.swift"],
  ["widget", "RunSheetLiveActivity.swift"],
  // The attributes are compiled into the app *and* the widget: ActivityKit
  // pairs an activity with the widget that draws it by the name of this type,
  // so both binaries have to contain it. Copied rather than kept in two places.
  ["modules/run-sheet-activity/ios", "RunSheetActivityAttributes.swift"],
];

const INFO_PLIST = ["widget", `${TARGET}-Info.plist`];

/** The iOS the widget needs. ActivityKit's content API lands in 16.2. */
const DEPLOYMENT_TARGET = "16.2";

module.exports = function withRunSheetWidget(config) {
  return withXcodeProject(withWidgetSources(config), (config) => {
    addWidgetTarget(config.modResults, {
      bundleIdentifier: `${config.ios?.bundleIdentifier}.${TARGET}`,
      developmentTeam:
        config.ios?.appleTeamId ?? process.env.APPLE_TEAM_ID ?? undefined,
      version: config.version ?? "1.0.0",
      buildNumber: config.ios?.buildNumber ?? "1",
    });
    return config;
  });
};

/** Copy the Swift and the plist into the generated project. */
function withWidgetSources(config) {
  return withDangerousMod(config, [
    "ios",
    (config) => {
      const from = config.modRequest.projectRoot;
      const to = path.join(config.modRequest.platformProjectRoot, TARGET);
      fs.mkdirSync(to, { recursive: true });

      for (const [dir, file] of [...SOURCES, INFO_PLIST]) {
        fs.copyFileSync(path.join(from, dir, file), path.join(to, file));
      }
      return config;
    },
  ]);
}

/**
 * Add the target, its build phases and its settings, and embed it in the app.
 *
 * `addTarget` does more than its name suggests: as well as the target it
 * creates the product reference and the app's "Copy Files" phase that embeds
 * the `.appex`. What it does not do is give the target anywhere to compile
 * from, which is the rest of this.
 */
function addWidgetTarget(project, options) {
  if (project.pbxTargetByName(TARGET)) return;

  const app = project.getFirstTarget();
  if (!app?.firstTarget?.productType?.includes("product-type.application")) {
    throw new Error(
      `${TARGET}: expected the app to be the project's first target, found ` +
        `${app?.firstTarget?.productType ?? "nothing"}. The widget is embedded ` +
        `into the first target, so it would be embedded into the wrong one.`,
    );
  }

  const group = project.addPbxGroup([], TARGET, TARGET);
  project.addToPbxGroup(group.uuid, rootGroupKey(project));

  const target = project.addTarget(
    TARGET,
    "app_extension",
    TARGET,
    options.bundleIdentifier,
  );

  // The phases have to exist before anything can be added to them.
  project.addBuildPhase([], "PBXSourcesBuildPhase", "Sources", target.uuid);
  project.addBuildPhase([], "PBXResourcesBuildPhase", "Resources", target.uuid);
  project.addBuildPhase([], "PBXFrameworksBuildPhase", "Frameworks", target.uuid);

  for (const [, file] of SOURCES) {
    project.addSourceFile(file, { target: target.uuid }, group.uuid);
  }

  // So the extension is built before the app tries to embed it. Both sections
  // have to exist first: a fresh Expo project has neither, and `xcode` writes
  // the dependency only if it finds them — silently doing nothing otherwise,
  // which surfaces much later as an app embedding an `.appex` that was never
  // built.
  const objects = project.hash.project.objects;
  objects.PBXTargetDependency ??= {};
  objects.PBXContainerItemProxy ??= {};
  project.addTargetDependency(app.uuid, [target.uuid]);
  if (objects.PBXNativeTarget[app.uuid].dependencies.length === 0) {
    throw new Error(`${TARGET}: the app was left with no dependency on it.`);
  }

  applyBuildSettings(project, target.uuid, options);
}

/** The project's root group — the one with neither a name nor a path. */
function rootGroupKey(project) {
  const groups = project.hash.project.objects.PBXGroup;
  for (const [key, group] of Object.entries(groups)) {
    if (key.endsWith("_comment")) continue;
    if (group.name === undefined && group.path === undefined) return key;
  }
  throw new Error(`${TARGET}: the project has no root group to add it to.`);
}

/**
 * What `addTarget` leaves out.
 *
 * The versions are the interesting ones. The Info.plist asks for
 * `$(MARKETING_VERSION)` and `$(CURRENT_PROJECT_VERSION)`, and App Store
 * Connect rejects an upload whose extension disagrees with its app about
 * either. `scripts/build-ipa.sh` passes both to `xcodebuild`, which overrides
 * every target at once; these are what make a plain `expo run:ios` produce a
 * valid bundle as well.
 */
function applyBuildSettings(project, targetUuid, options) {
  const settings = {
    CLANG_ENABLE_MODULES: "YES",
    CODE_SIGN_STYLE: "Automatic",
    CURRENT_PROJECT_VERSION: `"${options.buildNumber}"`,
    GENERATE_INFOPLIST_FILE: "NO",
    IPHONEOS_DEPLOYMENT_TARGET: DEPLOYMENT_TARGET,
    MARKETING_VERSION: `"${options.version}"`,
    SWIFT_EMIT_LOC_STRINGS: "YES",
    SWIFT_VERSION: "5.0",
    // iPhone only, like the app: an iPad has no lock screen worth putting this
    // on and cannot do Tap to Pay either.
    TARGETED_DEVICE_FAMILY: '"1"',
    ...(options.developmentTeam
      ? { DEVELOPMENT_TEAM: options.developmentTeam }
      : {}),
  };

  const target = project.pbxNativeTargetSection()[targetUuid];
  const lists = project.pbxXCConfigurationList();
  const configurations = project.pbxXCBuildConfigurationSection();

  for (const ref of lists[target.buildConfigurationList].buildConfigurations) {
    Object.assign(configurations[ref.value].buildSettings, settings);
  }
}
